.claude/settings.json:
{
  "hooks": {
    "SessionStart": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "command -v sandbox >/dev/null 2>&1 && { sandbox skills check >/dev/null 2>&1 || sandbox skills sync >/dev/null 2>&1; sandbox notes context; } || true"
          }
        ]
      }
    ],
    "PreToolUse": [
      {
        "matcher": "Edit|Write",
        "hooks": [
          {
            "type": "command",
            "command": "command -v sandbox >/dev/null 2>&1 && sandbox hooks gate || true"
          }
        ]
      }
    ]
  }
}
